from collections import Counter

def solve(nums, k):
    count = Counter(nums).values()
    max_freq = max(count)
    freq_list = []
    for num, freq in Counter(nums).items():
        if freq == max_freq:
            freq_list.append(num)
    return freq_list[:k]

from collections import Counter

def solve(nums, k):
    counts = Counter(nums).most_common()
    max_freq = counts[0][1]
    top_k = []
    for val, freq in counts:
        if freq < max_freq:
            break
        top_k.append(val)
        if len(top_k) == k:
            break
    return top_k

