def solve(intervals):
    if not intervals:
        return []

    # Sort intervals based by start time
    intervals.sort(key=lambda x: x[0])

    merged = [intervals[0]]

    for current in intervals[1:]:
        prev = merged[-1]
        if current[0] <= prev[1]:
            # Merge the intervals
            merged[-1][1] = max(prev[1], current[1])
        else:
            merged.append current

    return merged

