from collections import Counter

def solve(nums, k):
    count = Counter(nums)
    values = list(count.values())
    max_freq = max(values)
    freq_list = []
    for num, freq in count.items():
        if freq == max_freq:
            freq_list.append(num)
    return freq_list[:k]

