def solve(nums, k):
    def partial_sort(arr, k):
        heap = arr[:k]
        heapq.heapify(heap)
        for num in arr[k:]:
            if num < heap[0]:
                heapq.heappop(heap)
                heapq.heappush(heap, num)
        return heap[0]

    return partial_sort(nums, k)

