def solve(intervals):
    if not intervals:
        return 0

    # Sort intervals by end time
    intervals.sort(key=lambda x: x[1])

    removed = 0
    end = intervals[0][1]

    for start, current_end in intervals[1:]:
        if start < end:
            # Overlapping, remove this interval
            removed += 1
        else:
            # No overlap, update end to current_end
            end = current_end

    return removed

