from collections import Counter

def solve(nums, k):
    count = Counter(nums)
    freq_values = list(count.values())
    max_freq = max(freq_values)
    max_freq_count = freq_values.count(max_freq)
    if max_freq_count >= k:
        return list(count.keys())[freq_values.index(max_freq, 0, k)]
    else:
        return list(count.keys())[freq_values.index(max_freq, 0, k + max_freq_count)]

