    top_k = []
    for num, count in frequency.items():
        if len(top_k) < k:
            top_k.append((count, num))
        else:
            # Find the element with the smallest frequency in top_k
            min_freq = min(top_k, key=lambda x: x[0])[0]
            if count > min_freq:
                # Replace the element with the smallest frequency
                top_k.remove((min_freq, top_k[0][1]))
